/**
 * Read-only functional regression checks for SFC-01/SFC-02.
 * Runs only against a dedicated QA deployment, with synthetic user accounts.
 * No accounts, secrets or test fixtures are generated by this script.
 */
import { expect, request, test } from '@playwright/test';
import { existsSync, readFileSync } from 'node:fs';

const manifestPath = process.env.ACULTA_SECURITY_QA_FIXTURE || '';
const data = manifestPath && existsSync(manifestPath)
  ? JSON.parse(readFileSync(manifestPath, 'utf8'))
  : null;
const ready = data?.isolated === true && data?.originForum;
const denied = [301, 302, 303, 307, 308, 401, 403, 404];

function stateReady(name) {
  return ready && typeof data?.states?.[name] === 'string' && existsSync(data.states[name]);
}

async function snapshotAs(accountName, origin, path, withHtmx = false) {
  const ctx = await request.newContext({
    ...(accountName ? { storageState: data.states[accountName] } : {}),
  });
  try {
    const response = await ctx.get(new URL(path, origin).toString(), {
      maxRedirects: 0,
      headers: withHtmx ? { 'HX-Request': 'true' } : {},
    });
    return { status: response.status(), body: await response.text() };
  } finally {
    await ctx.dispose();
  }
}

const commentRoute = (cid) => '/discussoes/' + encodeURIComponent(String(cid)) + '/controles';
const topicRoute = (nid) => '/forum/topicos/' + encodeURIComponent(String(nid)) + '/controles';

test.describe('SFC-01 - moderation of Comments is purpose- and entity-scoped', () => {
  test('anonymous and ordinary account cannot inspect comment controls', async () => {
    test.skip(!ready || !data?.ids?.publicForumComment || !stateReady('common'), 'Needs isolated QA fixtures.');
    const path = commentRoute(data.ids.publicForumComment);
    expect(denied).toContain((await snapshotAs(null, data.originForum, path, true)).status);
    expect(denied).toContain((await snapshotAs('common', data.originForum, path, true)).status);
  });

  test('forum-only moderator cannot moderate Wiki, Magazine or LMS host comments', async () => {
    test.skip(!stateReady('forumModerator') || !data?.originWiki || !data?.originMagazine
      || !data?.originCourses || !data?.ids?.wikiComment || !data?.ids?.magazineComment
      || !data?.ids?.lmsComment, 'Requires Forum-only role and contextual comments.');
    for (const [origin, id] of [
      [data.originWiki, data.ids.wikiComment],
      [data.originMagazine, data.ids.magazineComment],
      [data.originCourses, data.ids.lmsComment],
    ]) {
      const result = await snapshotAs('forumModerator', origin, commentRoute(id), true);
      expect(denied, 'foreign comment moderation on ' + origin).toContain(result.status);
    }
  });

  test('forum moderator cannot open a revoked/private Group comment', async () => {
    test.skip(!stateReady('forumModerator') || !data?.ids?.restrictedForumComment,
      'Requires a restricted Forum topic not viewable by forumModerator.');
    const result = await snapshotAs('forumModerator', data.originForum, commentRoute(data.ids.restrictedForumComment), true);
    expect(denied).toContain(result.status);
    if (data?.markers?.privateComment) {
      expect(result.body).not.toContain(data.markers.privateComment);
    }
  });

  test('Forgeable HX-Request is not sufficient, and is required on allowed requests', async () => {
    test.skip(!stateReady('forumModerator') || !data?.ids?.publicForumComment,
      'Requires a currently viewable public Forum Comment.');
    const path = commentRoute(data.ids.publicForumComment);
    expect(denied).toContain((await snapshotAs('forumModerator', data.originForum, path, false)).status);
    expect((await snapshotAs('forumModerator', data.originForum, path, true)).status).toBe(200);
  });

  test('Growroom archive cannot be moderated through modern Forum controls', async () => {
    test.skip(!stateReady('adminComments') || !data?.ids?.legacyForumComment,
      'Requires authenticated admin and a legacy Growroom Comment.');
    const result = await snapshotAs('adminComments', data.originForum, commentRoute(data.ids.legacyForumComment), true);
    expect(denied).toContain(result.status);
  });
});

test.describe('SFC-02 - topic popup and CGU metadata are not IDORs', () => {
  test('topic mover without membership cannot inspect a restricted topic', async () => {
    test.skip(!stateReady('forumMoverNonMember') || !data?.ids?.restrictedForumTopic,
      'Requires Group restricted topic and mover who is not a member.');
    const result = await snapshotAs('forumMoverNonMember', data.originForum, topicRoute(data.ids.restrictedForumTopic));
    expect(denied).toContain(result.status);
    if (data?.markers?.privateTitle) {
      expect(result.body).not.toContain(data.markers.privateTitle);
    }
    if (data?.markers?.privateCguNotes) {
      expect(result.body).not.toContain(data.markers.privateCguNotes);
    }
  });

  test('topic mover can view an authorized topic, but not CGU notes without CGU scope', async () => {
    test.skip(!stateReady('forumMoverNonMember') || !data?.ids?.publicForumTopic,
      'Requires mover grant and accessible public topic.');
    const result = await snapshotAs('forumMoverNonMember', data.originForum, topicRoute(data.ids.publicForumTopic));
    expect(result.status).toBe(200);
    if (data?.markers?.publicCguNotes) {
      expect(result.body).not.toContain(data.markers.publicCguNotes);
    }
  });

  test('different account in the same browser run does not inherit allowed popup cache', async () => {
    test.skip(!stateReady('forumMoverMember') || !stateReady('forumMoverNonMember')
      || !data?.ids?.restrictedForumTopic, 'Requires two distinct Group membership states.');
    const path = topicRoute(data.ids.restrictedForumTopic);
    expect((await snapshotAs('forumMoverMember', data.originForum, path)).status).toBe(200);
    expect(denied).toContain((await snapshotAs('forumMoverNonMember', data.originForum, path)).status);
  });

  test('Forum popup is not served from the Magazine domain', async () => {
    test.skip(!stateReady('forumMoverMember') || !data?.originMagazine || !data?.ids?.publicForumTopic,
      'Requires two valid domains and a mover test account.');
    const result = await snapshotAs('forumMoverMember', data.originMagazine, topicRoute(data.ids.publicForumTopic));
    expect(denied).toContain(result.status);
  });
});
